//!
//! Generated by `tools/track_cook/build_atlas.py`. Do not edit by hand.

/// Visual block dimension in texels (1024x1024).
pub const BLOCK_DIM: usize = 1024;
/// Width of a single visual block in texels.
pub const WIDTH: usize = 1024;
/// Height of a single visual block in texels.
pub const HEIGHT: usize = 1024;
/// Decompressed VRAM tile dimension in texels (64x64).
pub const TILE_DIM: usize = 64;
/// Number of 64x64 tiles along each axis of a 1024x1024 block (16).
pub const TILES_PER_BLOCK_AXIS: usize = 16;
/// Total number of 64x64 tiles per 1024x1024 block (256).
pub const TILES_PER_BLOCK: usize = 256;
/// Number of authored circuits, one 1024x1024 block each.
pub const COUNT: usize = 24;
/// Maximum bytes per 1024x1024 compressed block (500 KB = 512,000 bytes).
pub const BLOCK_MAX_BYTES: usize = 512000;
/// Number of 2048-byte CD sectors allocated per circuit block (250 sectors = 500 KB).
pub const BLOCK_SECTORS: usize = 250;
/// Restart marker interval in MCUs (4 MCUs = 64x16 pixels).
pub const RESTART_INTERVAL: usize = 4;
/// Total restart intervals in one 1024x1024 block.
pub const RESTART_INTERVAL_COUNT: usize = 1024;
/// Independently decodable 64x16 QOI segments in one 1024x1024 block.
pub const SEGMENT_COUNT: usize = 1024;
/// Raw uncompressed 16-bit BGR555 halfwords per 64x64 tile.
pub const RAW_TILE_HALFWORDS: usize = TILE_DIM * TILE_DIM;
/// Raw uncompressed byte count per 64x64 tile (8,192 bytes = 8 KB).
pub const RAW_TILE_BYTES: usize = RAW_TILE_HALFWORDS * 2;
